create function tenant_inventory_choices(p_company uuid,p_product text,p_warehouse text,p_query text default '',p_page integer default 1,p_options jsonb default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp set app.tenant_id='' as $$ begin
 if not tenant_verified_user() or company_role(p_company) is null or not tenant_commerce_enabled(p_company) or not(tenant_permission(p_company,'inventory.read',null,p_warehouse) or tenant_permission(p_company,'orders.manage',null,p_warehouse) or tenant_permission(p_company,'affiliates.manage',null,p_warehouse)) then raise exception 'Forbidden';end if;
 if p_warehouse is null or p_product is null or length(coalesce(p_query,''))>100 or p_page is null or p_page not between 1 and 100000 or(p_options is not null and jsonb_typeof(p_options)<>'object') then raise exception 'Invalid unit search';end if;perform set_config('app.tenant_id',p_company::text,true);
 return jsonb_build_object('tracking_mode',case when tenant_serial_enabled(p_company,p_product) then 'serial' else 'none' end,
 'count',(select count(*) from tenant_serial_units u where u.company_id=p_company and u.product_id=p_product and u.warehouse_id=p_warehouse and u.state='available' and(p_options is null or u.options=p_options) and(coalesce(p_query,'')='' or position(lower(p_query) in lower(coalesce(u.serial,'')||' '||coalesce(u.imei,'')))>0)),
 'units',coalesce((select jsonb_agg(to_jsonb(t)) from(select u.id,u.serial,u.imei,u.options,u.state from tenant_serial_units u where u.company_id=p_company and u.product_id=p_product and u.warehouse_id=p_warehouse and u.state='available' and(p_options is null or u.options=p_options) and(coalesce(p_query,'')='' or position(lower(p_query) in lower(coalesce(u.serial,'')||' '||coalesce(u.imei,'')))>0) order by u.serial,u.imei,u.id limit 50 offset(p_page-1)*50)t),'[]'));
end $$;
alter function tenant_inventory_choices(uuid,text,text,text,integer,jsonb) owner to edge_tenant_executor;
revoke all on function tenant_inventory_choices(uuid,text,text,text,integer,jsonb) from public,anon,authenticated;
grant execute on function tenant_inventory_choices(uuid,text,text,text,integer,jsonb) to authenticated;

create function tenant_inventory_unit_json(p_company uuid,p_unit uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',u.id,'product_id',u.product_id,'product_name',p.name,'sku',p.sku,'warehouse_id',u.warehouse_id,'warehouse_name',w.name,'serial',u.serial,'imei',u.imei,'state',u.state,'options',u.options,'bin',u.bin,'condition',u.condition,'acquisition_date',u.acquisition_date,'warranty_until',u.warranty_until,'source_reference',u.source_reference,'created_at',u.created_at,'tracking_mode',case when tenant_serial_enabled(p_company,u.product_id) then 'serial' else 'none' end,
 'can_adjust',tenant_permission(p_company,'inventory.adjust',null,u.warehouse_id),'can_finance',tenant_permission(p_company,'finance.manage',null,u.warehouse_id),'can_warranty',tenant_permission(p_company,'catalogue.edit'),
 'acquisition_cost_kobo',case when tenant_permission(p_company,'finance.read',null,u.warehouse_id) then u.acquisition_cost_kobo::text else null end,
 'recorded_unit_cost_kobo',case when tenant_permission(p_company,'finance.read',null,u.warehouse_id) then p.cost_kobo::text else null end,
 'supplier_name',case when tenant_permission(p_company,'procurement.manage',null,u.warehouse_id) then s.name else null end,
 'release_id',u.release_id,'order_id',u.order_id,'pos_sale_id',u.pos_sale_id,'supersedes_id',u.supersedes_id)
 from tenant_serial_units u join products p on p.company_id=u.company_id and p.id=u.product_id join warehouses w on w.company_id=u.company_id and w.id=u.warehouse_id left join suppliers s on s.company_id=u.company_id and s.id=u.supplier_id where u.company_id=p_company and u.id=p_unit and tenant_permission(p_company,'inventory.read',null,u.warehouse_id)
$$;
alter function tenant_inventory_unit_json(uuid,uuid) owner to edge_tenant_executor;
revoke all on function tenant_inventory_unit_json(uuid,uuid) from public,anon,authenticated;
grant execute on function tenant_inventory_unit_json(uuid,uuid) to edge_tenant_executor;

create function tenant_inventory_snapshot(p_company uuid,p_warehouse text default null,p_product text default null,p_query text default '',p_state text default '',p_page integer default 1,p_unit uuid default null,p_history_page integer default 1) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp set app.tenant_id='' as $$
declare unit_record tenant_serial_units;begin
 if not tenant_verified_user() or company_role(p_company) is null or not tenant_commerce_enabled(p_company) or not tenant_any_permission(p_company,'inventory.read') then raise exception 'Forbidden';end if;
 if p_page is null or p_page not between 1 and 100000 or p_history_page is null or p_history_page not between 1 and 100000 or length(coalesce(p_query,''))>100 or coalesce(p_state,'') not in ('','available','reserved','custody','transit','sold','quarantine','damaged','missing','retired') then raise exception 'Invalid inventory filters';end if;
 perform set_config('app.tenant_id',p_company::text,true);
 if p_warehouse is not null and not tenant_permission(p_company,'inventory.read',null,p_warehouse) then raise exception 'Forbidden';end if;
 if p_unit is not null then select * into unit_record from tenant_serial_units where company_id=p_company and id=p_unit;if not found or not tenant_permission(p_company,'inventory.read',null,unit_record.warehouse_id) then raise exception 'Forbidden';end if;end if;
 return jsonb_build_object('access',saas_access(p_company),'can_configure',tenant_permission(p_company,'catalogue.edit') and tenant_permission(p_company,'inventory.adjust'),'can_adjust',tenant_any_permission(p_company,'inventory.adjust'),'can_finance',tenant_permission(p_company,'finance.manage',null,p_warehouse),'can_pos',tenant_any_permission(p_company,'orders.read'),'can_books',tenant_any_permission(p_company,'finance.read'),'can_affiliates',tenant_any_permission(p_company,'affiliates.read'),
 'warehouses',coalesce((select jsonb_agg(jsonb_build_object('id',w.id,'name',w.name)) from warehouses w where w.company_id=p_company and tenant_permission(p_company,'inventory.read',null,w.id)),'[]'),
 'products',coalesce((select jsonb_agg(to_jsonb(t)) from(select p.id,p.name,p.sku,p.options,p.active,coalesce(c.mode,'none') tracking_mode,coalesce(c.safety_stock,0) safety_stock,c.maximum_stock,coalesce(c.lead_time_days,7) lead_time_days,coalesce(c.warranty_days,0) warranty_days,p.reorder_level from products p left join tenant_tracking_products c on c.company_id=p.company_id and c.product_id=p.id where p.company_id=p_company and p.archived_at is null and(p_product is null or p.id=p_product) order by p.name,p.id limit 200)t),'[]'),
 'suppliers',case when tenant_permission(p_company,'procurement.manage') then coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name)) from suppliers s where s.company_id=p_company and s.active),'[]') else '[]' end,
 'book_value_kobo',case when tenant_permission(p_company,'finance.read',null,p_warehouse) and tenant_permission(p_company,'inventory.read',null,p_warehouse) then(select coalesce(sum(l.debit_kobo-l.credit_kobo),0)::text from tenant_journal_lines l join tenant_journals j on j.company_id=l.company_id and j.id=l.journal_id join tenant_accounts a on a.company_id=l.company_id and a.code=l.account_code where l.company_id=p_company and a.subtype='inventory' and(p_warehouse is null or j.warehouse_id=p_warehouse) and tenant_permission(p_company,'inventory.read',null,j.warehouse_id) and tenant_permission(p_company,'finance.read',null,j.warehouse_id)) else null end,
 'availability',(select jsonb_build_object('on_hand',coalesce(sum(i.on_hand),0),'reserved',coalesce(sum(i.reserved),0),'available',coalesce(sum(i.on_hand-i.reserved),0)) from tenant_inventory i where i.company_id=p_company and(p_product is null or i.product_id=p_product) and(p_warehouse is null or i.warehouse_id=p_warehouse) and tenant_permission(p_company,'inventory.read',null,i.warehouse_id)),
 'custody',(select jsonb_build_object('company_custody',coalesce(sum(r.quantity-r.sold-r.returned-r.received-r.damaged-r.missing) filter(where r.relationship not in ('interbranch','wholesale_credit')),0),'in_transit',coalesce(sum(r.quantity-r.sold-r.returned-r.received-r.damaged-r.missing) filter(where r.relationship='interbranch'),0),'wholesale_with_partners',coalesce(sum(r.quantity-r.sold-r.returned-r.received-r.damaged-r.missing) filter(where r.relationship='wholesale_credit'),0)) from tenant_custody_releases r where r.company_id=p_company and r.status='released' and(p_product is null or r.product_id=p_product) and(p_warehouse is null or r.warehouse_id=p_warehouse) and tenant_permission(p_company,'inventory.read',null,r.warehouse_id)),
 'inbound_in_transit',(select coalesce(sum(r.quantity-r.sold-r.returned-r.received-r.damaged-r.missing),0) from tenant_custody_releases r where r.company_id=p_company and r.relationship='interbranch' and r.status='released' and(p_product is null or r.product_id=p_product) and(p_warehouse is null or r.destination_warehouse=p_warehouse) and tenant_permission(p_company,'inventory.read',null,r.destination_warehouse)),
 'identity_counts',(select coalesce(jsonb_object_agg(state,n),'{}') from(select u.state,count(*) n from tenant_serial_units u where u.company_id=p_company and(p_product is null or u.product_id=p_product) and(p_warehouse is null or u.warehouse_id=p_warehouse) and tenant_permission(p_company,'inventory.read',null,u.warehouse_id) group by u.state)t),
 'unit_count',(select count(*) from tenant_serial_units u join products p on p.company_id=u.company_id and p.id=u.product_id where u.company_id=p_company and(p_product is null or u.product_id=p_product) and(p_warehouse is null or u.warehouse_id=p_warehouse) and(p_unit is null or u.id=p_unit) and(p_state='' or u.state=p_state) and tenant_permission(p_company,'inventory.read',null,u.warehouse_id) and(coalesce(p_query,'')='' or position(lower(p_query) in lower(coalesce(u.serial,'')||' '||coalesce(u.imei,'')||' '||p.name||' '||coalesce(p.sku,'')))>0)),
 'units',coalesce((select jsonb_agg(tenant_inventory_unit_json(p_company,t.id)) from(select u.id from tenant_serial_units u join products p on p.company_id=u.company_id and p.id=u.product_id where u.company_id=p_company and(p_product is null or u.product_id=p_product) and(p_warehouse is null or u.warehouse_id=p_warehouse) and(p_unit is null or u.id=p_unit) and(p_state='' or u.state=p_state) and tenant_permission(p_company,'inventory.read',null,u.warehouse_id) and(coalesce(p_query,'')='' or position(lower(p_query) in lower(coalesce(u.serial,'')||' '||coalesce(u.imei,'')||' '||p.name||' '||coalesce(p.sku,'')))>0) order by u.created_at desc,u.id limit 50 offset case when p_unit is null then(p_page-1)*50 else 0 end)t),'[]'),
 'history_count',case when p_unit is null then 0 else(select count(*) from tenant_serial_events e where e.company_id=p_company and e.unit_id=p_unit and tenant_permission(p_company,'inventory.read',null,e.next_warehouse)) end,
 'history',case when p_unit is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(t)) from(select e.* from tenant_serial_events e where e.company_id=p_company and e.unit_id=p_unit and tenant_permission(p_company,'inventory.read',null,e.next_warehouse) order by e.created_at desc,e.id limit 25 offset(p_history_page-1)*25)t),'[]') end,
 'cost_history_count',case when p_unit is null or not tenant_permission(p_company,'finance.read',null,unit_record.warehouse_id) then 0 else(select count(*) from tenant_serial_cost_history h where h.company_id=p_company and h.unit_id=p_unit) end,
 'cost_history',case when p_unit is null or not tenant_permission(p_company,'finance.read',null,unit_record.warehouse_id) then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(t)) from(select h.id,h.previous_kobo::text,h.new_kobo::text,h.source_reference,h.actor,h.command_id,h.created_at from tenant_serial_cost_history h where h.company_id=p_company and h.unit_id=p_unit order by h.created_at desc,h.id limit 25 offset(p_history_page-1)*25)t),'[]') end);
end $$;
alter function tenant_inventory_snapshot(uuid,text,text,text,text,integer,uuid,integer) owner to edge_tenant_executor;
revoke all on function tenant_inventory_snapshot(uuid,text,text,text,text,integer,uuid,integer) from public,anon,authenticated;
grant execute on function tenant_inventory_snapshot(uuid,text,text,text,text,integer,uuid,integer) to authenticated;
